   116  bool HeifPixelImage::add_plane(heif_channel channel, int width, int height, int bit_depth)
   117  {
   118    assert(width >= 0);
   119    assert(height >= 0);
   120    assert(bit_depth >= 1);
   121
   122    // use 16 byte alignment
   123    int alignment = 16; // must be power of two
   124
   125    ImagePlane plane;
   126    plane.width = width;
   127    plane.height = height;
   128
   129
   130    // for backwards compatibility, allow for 24/32 bits for RGB/RGBA interleaved chromas
   131
   132    if (m_chroma == heif_chroma_interleaved_RGB && bit_depth==24) {
   133      bit_depth = 8;
   134    }
   135
   136    if (m_chroma == heif_chroma_interleaved_RGBA && bit_depth==32) {
   137      bit_depth = 8;
   138    }
   139
   140    plane.bit_depth = bit_depth;
   141
   142
   143    int bytes_per_component = (bit_depth+7)/8;
   144    int bytes_per_pixel = num_interleaved_pixels_per_plane(m_chroma) * bytes_per_component;
   145
   146    plane.stride = width * bytes_per_pixel;
   147
   148    plane.stride = (plane.stride+alignment-1) & ~(alignment-1);
   149
   150    try {
   151      plane.allocated_mem = new uint8_t[height * plane.stride + alignment-1];
   152      plane.mem = plane.allocated_mem;
   153
   154      // shift beginning of image data to aligned memory position
   155
   156      auto mem_start_addr = (uint64_t)plane.mem;
   157      auto mem_start_offset = (mem_start_addr & (alignment-1));
   158      if (mem_start_offset != 0) {
   159        plane.mem += alignment - mem_start_offset;
   160      }
   161
   162      m_planes.insert(std::make_pair(channel, std::move(plane)));
   163    }
   164    catch (const std::bad_alloc& excpt) {
   165      return false;
   166    }
   167
   168    return true;
   169  }
